import { defineSlot } from '../Slot';

/**
 * Extra columns of the people table. A contribution renders one `<th>` in the header slot and one
 * `<td>` per person in the cells slot, at the same order, so the columns line up.
 */
export const PersonHeads = defineSlot<{ sheetId: string; user: string }>('person.heads');
export const PersonCells = defineSlot<{ sheetId: string; user: string; personId: number }>('person.cells');
    sheet.count += mine.count;
  }
  sheet.cents = trimmedSum([...byPerson.values()].map((o) => o.cents));
  return { byPerson, sheet };
}

function OverdueHeads() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

// A person's overdue count and overdue-total: their counted OPEN claims past their due-by, and those claims' due added up.
function OverdueCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const mine = useOverdue(sheetId).byPerson.get(personId) ?? { count: 0, cents: 0n };
  return (
    <>
      <td data-testid="person-overdue-count">{mine.count}</td>
      <td data-testid="person-overdue-total">{showHundredths(mine.cents)}</td>
    </>
  );
}

// A claim's due-by (the terms-th business day after its date, by the terms fixed when it was added and the sheet's holidays now) and whether it is overdue (OPEN and due-by plus its grade's grace before the sheet's today).
function ClaimOverdue({ sheetId, personId, claim }: { sheetId: string; user: string; personId: number; claim: { status: string; date: string; dueBy: string; deferred?: boolean } }) {
  const isOverdue = useIsOverdue(sheetId);
  const person = usePeople(sheetId).data?.find((p) => p.id === personId);
  return (
    <>
      Due by <span data-testid="claim-due-by">{claim.dueBy}</span>{' '}
      Overdue <span data-testid="claim-overdue">{isOverdue(claim, gradeOn(person, claim.date)) ? 'yes' : 'no'}</span>{' '}
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal({ sheetId }: { sheetId: string; user: string }) {
  const { sheet } = useOverdue(sheetId);
  return (
    <section data-testid="overdue-rollup">
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{sheet.count}</strong>{' '}
        Overdue total: <strong data-testid="rollup-overdue-total">{showHundredths(sheet.cents)}</strong>
      </p>
    </section>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 25, Component: OverdueHeads }),
  PersonCells.fill({ order: 25, Component: OverdueCells }),
  ClaimCells.fill({ order: 12, Component: ClaimOverdue }),
  SheetBody.fill({ order: 26, Component: OverdueTotal }),
];
  const last = useLastPersonAction(sheetId, personId, add.submittedAt);
  const patrons = person?.patrons ?? [];
  const offered = people.filter((p) => p.id !== personId && !patrons.includes(p.name));
  const shares = person?.patronShares ?? [];
  let backing = 0n;
  if (today !== undefined) {
    const since = addDays(today, -89);
    // Each patron's share in hundredths of a percent, by their id.
    const shareOf = new Map<number, bigint>();
    for (const s of shares) {
      const patron = people.find((p) => p.name === s.name);
      if (patron) shareOf.set(patron.id, toHundredths(s.share));
    }
    // Cents times hundredths of a percent: ten-thousandths of a cent.
    let weighted = 0n;
    for (const c of claims) {
      const share = shareOf.get(c.personId);
      if (share === undefined || c.status !== 'SETTLED' || c.settledDue == null) continue;
      if (c.date < since || c.date > today) continue;
      weighted += toHundredths(c.settledDue) * share;
    }
    backing = roundHalfEven(weighted, 10_000n);
  }

  return (
    <>
      <td data-testid="person-patrons">{shares.map((s) => `${s.name} ${s.share}`).join(', ')}</td>
      <td data-testid="person-backing">{showHundredths(backing)}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {offered.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button type="button" data-testid="person-patron-add" disabled={add.isPending} onClick={() => add.mutate(chosen)}>
          Add patron
        </button>
        {add.isError && last && (
          <span data-testid="person-patron-error" role="alert">
            {add.error.message}
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
